//! 🧾️ Fixed member metadata is lent by the exact live typed read and its original parent operation.
use super::ChildEditorRead;
#[derive(Clone,Copy)]pub struct ChildMemberReadMetadata<'a>{pub parent_identity:usize,pub child_identity:usize,pub parent_artifact:&'a str,pub owner:&'a str,pub slot:&'a str,pub child_id:&'a str,pub artifact_id:&'a str,pub artifact_kind:&'a str,pub standard:&'a str,pub subset:&'a str,pub parent_revision:&'a[u8;32],pub child_revision:&'a[u8;32]}
impl<S> ChildEditorRead<'_,S>{pub fn member_metadata(&self)->ChildMemberReadMetadata<'_>{ChildMemberReadMetadata{parent_identity:self.parent_identity,child_identity:&self.entry.snapshot as*const _ as usize,parent_artifact:self.parent_artifact,owner:&self.entry.owner,slot:&self.entry.slot,child_id:&self.entry.child_id,artifact_id:&self.entry.artifact_id,artifact_kind:&self.entry.dialect.artifact_kind,standard:&self.entry.dialect.standard,subset:&self.entry.dialect.subset,parent_revision:self.parent_revision,child_revision:&self.entry.revision}}}
